-- =====================================================================
--  Cut & Schedule — Barber Shop Management System
--  Lumié Talent Paris
--  Database schema + demo data (dates are relative to the import date)
--
--  Demo accounts:
--    Owner  : admin1 / admin2026
--    Staff  : mark   / staff123   (also jay, luis)
--    Client : arizza / client123  (also paulo)
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS cut_schedule;
CREATE DATABASE cut_schedule CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cut_schedule;

-- ---------------------------------------------------------------------
-- Users (one login page for all roles; role is stored here)
-- ---------------------------------------------------------------------
CREATE TABLE users (
  id               INT AUTO_INCREMENT PRIMARY KEY,
  name             VARCHAR(100) NOT NULL,
  username         VARCHAR(100) UNIQUE NOT NULL,
  email            VARCHAR(150) UNIQUE NOT NULL,
  phone            VARCHAR(30)  NULL,
  password         VARCHAR(255) NOT NULL,
  role             ENUM('owner','staff','client') NOT NULL,
  status           ENUM('active','inactive') DEFAULT 'active',
  avatar           VARCHAR(255) NULL,
  remember_token   VARCHAR(64)  NULL,
  remember_expires DATETIME     NULL,
  created_at       DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Staff profile (salary is private; only the owner can see it)
-- ---------------------------------------------------------------------
CREATE TABLE staff_profiles (
  user_id     INT PRIMARY KEY,
  position    VARCHAR(60) NOT NULL DEFAULT 'Barber',
  salary      DECIMAL(10,2) NOT NULL DEFAULT 0,
  rating      DECIMAL(2,1) NOT NULL DEFAULT 5.0,
  work_start  TIME NOT NULL DEFAULT '08:00:00',
  work_end    TIME NOT NULL DEFAULT '19:00:00',
  work_days   VARCHAR(20) NOT NULL DEFAULT '1,2,3,4,5,6',
  bio         VARCHAR(255) NULL,
  CONSTRAINT fk_staff_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Service catalog
-- ---------------------------------------------------------------------
CREATE TABLE services (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  description VARCHAR(255) NULL,
  price       DECIMAL(10,2) NOT NULL,
  duration    INT NOT NULL,
  image       VARCHAR(255) NULL,
  status      ENUM('active','archived') DEFAULT 'active',
  sort_order  INT NOT NULL DEFAULT 0,
  created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CHECK (price > 0),
  CHECK (duration > 0)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Client profiles (walk-ins may have no login account)
-- ---------------------------------------------------------------------
CREATE TABLE clients (
  id                   INT AUTO_INCREMENT PRIMARY KEY,
  user_id              INT NULL UNIQUE,
  name                 VARCHAR(100) NOT NULL,
  email                VARCHAR(150) NULL,
  phone                VARCHAR(30)  NULL,
  discount_type        ENUM('none','senior','pwd') NOT NULL DEFAULT 'none',
  preferred_barber_id  INT NULL,
  preferred_service_id INT NULL,
  notes                TEXT NULL,
  avatar               VARCHAR(255) NULL,
  created_at           DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_client_user    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_client_barber  FOREIGN KEY (preferred_barber_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_client_service FOREIGN KEY (preferred_service_id) REFERENCES services(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Appointments
-- ---------------------------------------------------------------------
CREATE TABLE appointments (
  id               INT AUTO_INCREMENT PRIMARY KEY,
  client_id        INT NOT NULL,
  barber_id        INT NOT NULL,
  service_id       INT NOT NULL,
  appointment_date DATE NOT NULL,
  start_time       TIME NOT NULL,
  end_time         TIME NOT NULL,
  status           ENUM('pending','confirmed','in_progress','completed','cancelled') NOT NULL DEFAULT 'pending',
  base_price       DECIMAL(10,2) NOT NULL,
  discount_type    ENUM('none','senior','pwd') NOT NULL DEFAULT 'none',
  discount_amount  DECIMAL(10,2) NOT NULL DEFAULT 0,
  total_price      DECIMAL(10,2) NOT NULL,
  notes            TEXT NULL,
  created_by       INT NULL,
  completed_at     DATETIME NULL,
  created_at       DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_barber_date (barber_id, appointment_date),
  INDEX idx_date_status (appointment_date, status),
  INDEX idx_client (client_id),
  CONSTRAINT fk_appt_client  FOREIGN KEY (client_id)  REFERENCES clients(id)  ON DELETE CASCADE,
  CONSTRAINT fk_appt_barber  FOREIGN KEY (barber_id)  REFERENCES users(id)    ON DELETE RESTRICT,
  CONSTRAINT fk_appt_service FOREIGN KEY (service_id) REFERENCES services(id) ON DELETE RESTRICT,
  CONSTRAINT fk_appt_creator FOREIGN KEY (created_by) REFERENCES users(id)    ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Client visit notes written by staff
-- ---------------------------------------------------------------------
CREATE TABLE client_notes (
  id             INT AUTO_INCREMENT PRIMARY KEY,
  client_id      INT NOT NULL,
  staff_id       INT NULL,
  appointment_id INT NULL,
  note           TEXT NOT NULL,
  created_at     DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_note_client FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  CONSTRAINT fk_note_staff  FOREIGN KEY (staff_id)  REFERENCES users(id)   ON DELETE SET NULL,
  CONSTRAINT fk_note_appt   FOREIGN KEY (appointment_id) REFERENCES appointments(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Client favourites (barbers and services)
-- ---------------------------------------------------------------------
CREATE TABLE favorites (
  id         INT AUTO_INCREMENT PRIMARY KEY,
  client_id  INT NOT NULL,
  fav_type   ENUM('barber','service') NOT NULL,
  ref_id     INT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_fav (client_id, fav_type, ref_id),
  CONSTRAINT fk_fav_client FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- In-app notifications (bell icon)
-- ---------------------------------------------------------------------
CREATE TABLE notifications (
  id         INT AUTO_INCREMENT PRIMARY KEY,
  user_id    INT NOT NULL,
  title      VARCHAR(120) NOT NULL,
  message    VARCHAR(255) NOT NULL,
  link       VARCHAR(255) NULL,
  is_read    TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_user_read (user_id, is_read),
  CONSTRAINT fk_notif_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Newsletter subscribers ("Stay in the know" on the client landing page)
-- ---------------------------------------------------------------------
CREATE TABLE subscribers (
  id         INT AUTO_INCREMENT PRIMARY KEY,
  name       VARCHAR(100) NOT NULL,
  email      VARCHAR(150) NOT NULL UNIQUE,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Shop settings
-- ---------------------------------------------------------------------
CREATE TABLE settings (
  setting_key   VARCHAR(60) PRIMARY KEY,
  setting_value VARCHAR(255) NOT NULL
) ENGINE=InnoDB;

